 final ObjectMapper J=new ObjectMapper();String host;Path work;JsonNode f;final ArrayNode errors=J.createArrayNode();final ArrayNode timestampObservations=J.createArrayNode();
 record Conn(EchoAgentClient client,SessionHandle session) implements AutoCloseable {public void close()throws Exception{client.closeAsync().toCompletableFuture().get(10,TimeUnit.SECONDS);}}
