 JsonNode fail(CompletionStage<JsonNode> p)throws Exception{try{waitFor(p);throw new AssertionError("expected failure");}catch(ExecutionException e){Throwable t=e.getCause();while(t.getCause()!=null&&!(t instanceof EchoAgentException))t=t.getCause();yes(t instanceof EchoAgentException);EchoAgentException x=(EchoAgentException)t;eq(x.code(),"framework_error");yes(x.operation()!=null);if(x.operation().contains("delivery"))yes(x.getMessage().contains("stale delivery claim"));ObjectNode o=J.createObjectNode().put("code",x.code()).put("operation",x.operation()).put("message",x.getMessage());errors.add(o);return o;}}
 void fault(String action)throws Exception{Process p=new ProcessBuilder("python3",Path.of("../shared/testing/state_trace_delivery_fixture.py").toAbsolutePath().toString(),"--work",work.toString(),action).inheritIO().start();eq(p.waitFor(),0);}
 List<Path> jsonFiles(Path dir)throws Exception{try(var paths=Files.list(dir)){return paths.filter(p->p.toString().endsWith(".json")).toList();}}
