 ObjectNode state()throws Exception{ObjectNode proof=J.createObjectNode();try(Conn c=start()){SessionHandle s=c.session();for(String label:List.of("a","b")){JsonNode cp=f.path("checkpoint_"+label);eq(call(s,"state.checkpoint.save",f.path("scope_"+label).asText(),nativeValue(cp)),J.readTree("{\"ok\":true}"));sameTime(call(s,"state.checkpoint.get",cp.path("conversation_id").asText()).path("checkpoint"),cp,"timestamp");eq(call(s,"state.runtime.list",f.path("scope_"+label).asText()).path("runtime_state_ids"),J.createArrayNode().add(cp.path("conversation_id").asText()));}
 Path dir=work.resolve("state/runtime_state/_runtime_owners");Map<Path,byte[]>before=new LinkedHashMap<>();for(Path p:jsonFiles(dir))before.put(p,Files.readAllBytes(p));fault("block-owners");try{fail(s.invoke("state.checkpoint.save",List.of(f.path("scope_a").asText(),nativeValue(f.path("checkpoint_a")))));}finally{fault("unblock");}for(var e:before.entrySet())yes(Arrays.equals(e.getValue(),Files.readAllBytes(e.getKey())));call(s,"state.checkpoint.save",f.path("scope_a").asText(),nativeValue(f.path("checkpoint_a")));
 Path pa=null;for(Path p:jsonFiles(dir))if(J.readTree(p.toFile()).path("runtime_state_id").asText().equals(f.path("checkpoint_a").path("conversation_id").asText()))pa=p;yes(pa!=null);byte[]raw=Files.readAllBytes(pa);Files.writeString(pa,"{corrupt-owner");try{fail(s.invoke("state.checkpoint.get",List.of(f.path("checkpoint_a").path("conversation_id").asText())));}finally{Files.write(pa,raw);}
 JsonNode clear=call(s,"state.scope.clear",f.path("scope_a").asText());eq(clear.path("runtime_state_ids"),J.createArrayNode().add(f.path("checkpoint_a").path("conversation_id").asText()));yes(call(s,"state.checkpoint.get",f.path("checkpoint_a").path("conversation_id").asText()).path("checkpoint").isNull());sameTime(call(s,"state.checkpoint.get",f.path("checkpoint_b").path("conversation_id").asText()).path("checkpoint"),f.path("checkpoint_b"),"timestamp");
 for(Path p:jsonFiles(work.resolve("state/runtime_state/_scope_index")))if(J.readTree(p.toFile()).path("scope_id").asText().equals(f.path("scope_b").asText()))Files.delete(p);eq(call(s,"state.runtime.list",f.path("scope_b").asText()).path("runtime_state_ids"),J.createArrayNode().add(f.path("checkpoint_b").path("conversation_id").asText()));}
 try(Conn c=start()){JsonNode cp=call(c.session(),"state.checkpoint.get",f.path("checkpoint_b").path("conversation_id").asText()).path("checkpoint");sameTime(cp,f.path("checkpoint_b"),"timestamp");proof.set("after_real_host_restart",cp);}proof.set("errors",errors);addTimeEvidence(proof);return proof;}
 ObjectNode trace()throws Exception{ObjectNode proof=J.createObjectNode();try(Conn c=start()){SessionHandle s=c.session();Path blocked=work.resolve("trace-open-parent");Files.writeString(blocked,"regular file");fail(s.invoke("trace.store.open",List.of("jsonl",blocked.resolve("child").toString())));WireHandle h=handle(call(s,"trace.store.open","jsonl",f.path("trace_dir").asText()).path("resource"));call(s,"trace.run.save",h,nativeValue(f.path("trace")));JsonNode loaded=call(s,"trace.run.load",h,f.path("trace").path("run_id").asText()).path("run");sameTime(loaded,f.path("trace_expected"),"started_at","finished_at");
 Path logfile;try(var paths=Files.list(Path.of(f.path("trace_dir").asText()))){logfile=paths.filter(p->p.toString().endsWith(".jsonl")).findFirst().orElseThrow();}byte[]raw=Files.readAllBytes(logfile);yes(!new String(raw,java.nio.charset.StandardCharsets.UTF_8).contains("sk-abcdefghijklmnopqrstuvwxyz123456"));sameTime(J.readTree(new String(raw,java.nio.charset.StandardCharsets.UTF_8).split("\n")[0]),f.path("trace_expected"),"started_at","finished_at");proof.put("durable_raw",new String(raw,java.nio.charset.StandardCharsets.UTF_8));
 fault("block-trace");try{fail(s.invoke("trace.run.save",List.of(h,nativeValue(f.path("trace")))));sameTime(call(s,"trace.run.load",h,f.path("trace").path("run_id").asText()).path("run"),loaded,"started_at","finished_at");}finally{fault("unblock");}yes(Arrays.equals(raw,Files.readAllBytes(logfile)));call(s,"trace.run.save",h,nativeValue(f.path("trace")));JsonNode summaries=call(s,"trace.run.list_session",h,f.path("trace").path("session_id").asText()).path("summaries");eq(summaries.size(),1);sameTime(summaries.get(0),f.path("trace_summary_expected"),"started_at","finished_at");proof.set("summaries",summaries);proof.set("loaded",loaded);}
 try(Conn c=start()){WireHandle h=handle(call(c.session(),"trace.store.open","jsonl",f.path("trace_dir").asText()).path("resource"));JsonNode reopened=call(c.session(),"trace.run.load",h,f.path("trace").path("run_id").asText()).path("run");sameTime(reopened,f.path("trace_expected"),"started_at","finished_at");proof.set("after_real_host_restart",reopened);}proof.set("errors",errors);addTimeEvidence(proof);return proof;}
 Map<String,Object> claim(JsonNode c){Map<String,Object>m=new LinkedHashMap<>();c.fields().forEachRemaining(e->m.put(e.getKey(),nativeValue(e.getValue())));String n=c.path("attempt").asText();yes(new java.math.BigInteger(n).compareTo(new java.math.BigInteger("4294967295"))<=0);m.put("attempt",WireValues.u64(n));return m;}
 ObjectNode delivery()throws Exception{ObjectNode proof=J.createObjectNode().put("durability","in-memory same-instance only");try(Conn c=start()){SessionHandle s=c.session();WireHandle h=handle(call(s,"delivery.ledger.open").path("resource"));JsonNode msg=f.path("delivery");call(s,"delivery.enqueue",h,msg.path("message_id").asText(),msg.path("route").asText(),nativeValue(msg.path("payload")));CompletionStage<JsonNode>one=s.invoke("delivery.claim_next",List.of(h));CompletionStage<JsonNode>two=s.invoke("delivery.claim_next",List.of(h));JsonNode a=waitFor(one).path("claim"),b=waitFor(two).path("claim");if(Integer.parseInt(a.path("attempt").asText())>Integer.parseInt(b.path("attempt").asText())){JsonNode t=a;a=b;b=t;}eq(a.path("attempt").asText(),"1");eq(b.path("attempt").asText(),"2");for(JsonNode v:List.of(a,b)){eq(v.size(),6);eq(v.path("payload"),msg.path("payload"));eq(v.path("message_id"),msg.path("message_id"));yes(v.path("claimed_at").isTextual());}yes(!a.path("attempt_id").equals(b.path("attempt_id")));
 JsonNode before=call(s,"delivery.snapshot",h);eq(before.path("records").get(0).path("attempt_id"),b.path("attempt_id"));JsonNode seq=call(s,"delivery.recover",h);fail(s.invoke("delivery.transition",List.of(h,claim(a),"effect_started","turn-superseded")));eq(call(s,"delivery.snapshot",h),before);eq(call(s,"delivery.recover",h),seq);call(s,"delivery.transition",h,claim(b),"effect_started","turn-before-defer");one=s.invoke("delivery.claim_next",List.of(h));two=s.invoke("delivery.claim_next",List.of(h));yes(waitFor(one).path("claim").isNull()&&waitFor(two).path("claim").isNull());call(s,"delivery.defer",h,claim(b),"延迟重试🙂","2000-01-01T00:00:00Z");JsonNode third=call(s,"delivery.claim_next",h).path("claim");eq(third.path("attempt").asText(),"3");before=call(s,"delivery.snapshot",h);seq=call(s,"delivery.recover",h);
 for(String op:List.of("delivery.transition","delivery.defer","delivery.settle")){List<Object>args=switch(op){case "delivery.transition"->List.of(h,claim(a),"effect_started","turn-旧");case "delivery.defer"->List.of(h,claim(a),"旧请求","2000-01-01T00:00:00Z");default->Arrays.asList(h,claim(a),"completed",null,"turn-旧");};fail(s.invoke(op,args));eq(call(s,"delivery.snapshot",h),before);eq(call(s,"delivery.recover",h),seq);}call(s,"delivery.transition",h,claim(third),"effect_started","turn-新");call(s,"delivery.settle",h,claim(third),"completed",null,"turn-新");JsonNode snapshot=call(s,"delivery.snapshot",h);eq(snapshot.path("records").size(),1);eq(snapshot.path("records").get(0).path("outcome").asText(),"completed");eq(snapshot.path("records").get(0).path("attempt_id"),third.path("attempt_id"));JsonNode recovered=call(s,"delivery.recover",h);eq(call(s,"delivery.snapshot",h),snapshot);eq(call(s,"delivery.recover",h),recovered);proof.set("concurrent_claims",J.createArrayNode().add(a).add(b));proof.set("claim1",a);proof.set("claim2",third);proof.set("snapshot",snapshot);proof.set("recovery",recovered);}proof.set("errors",errors);return proof;}
 @Test void stateFullFieldsFaultAndRealHostRestart() throws Exception { runScene("state"); }
 @Test void traceJsonlFullSanitizedFieldsFaultAndRealHostRestart() throws Exception { runScene("trace"); }
 @Test void deliveryLatestClaimAuthorityStaleRejectionAndSameInstanceRecovery() throws Exception { runScene("delivery"); }
 void runScene(String scene) throws Exception {
     host = System.getenv("ECHO_AGENT_SDK_HOST");
     if ("1".equals(System.getenv("ECHO_AGENT_SDK_REQUIRE_HOST_E2E"))) assertTrue(host != null && !host.isBlank(), "required State/Trace/Delivery Host binary missing");
     assumeTrue(host != null && !host.isBlank(), "real Host binary required");
     work = Files.createTempDirectory("sdk-java-" + scene + "-");
     System.out.println("State/Trace/Delivery evidence " + scene + ": " + work);
     Process prep = new ProcessBuilder("python3", Path.of("../shared/testing/state_trace_delivery_fixture.py").toAbsolutePath().toString(), "--work", work.toString(), "prepare").inheritIO().start();
     eq(prep.waitFor(), 0);
     f = J.readTree(work.resolve("fixture.json").toFile());
     ObjectNode proof = switch (scene) { case "state" -> state(); case "trace" -> trace(); default -> delivery(); };
     Files.writeString(work.resolve(scene + "-observed.json"), J.writerWithDefaultPrettyPrinter().writeValueAsString(proof));
     eq(Files.readString(work.resolve("state/host/generation")).trim(), scene.equals("delivery") ? "1" : "2");
 }
